/**
 * Concatenates `supabase/migrations` into one script for the dashboard SQL editor,
 * for networks where neither the Postgres ports nor the Management API are reachable.
 * Each migration is followed by its bookkeeping row, so `supabase db push` and
 * `pnpm db:push` both treat it as already applied afterwards.
 *
 * `--reset` prepends a clean slate. The editor does not roll a failed script back, so
 * a half-applied run leaves objects behind and every retry dies on "already exists".
 * Migrations are not idempotent by design; starting over is the honest way out.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const MIGRATIONS_DIR = "supabase/migrations";
const OUTPUT = "supabase/bundle.sql";
const RESET = process.argv.includes("--reset");

const RESET_BLOCK = [
  "-- ⚠️  Drops every table, function and row this project owns. The extensions live in",
  "-- the `extensions` schema on Supabase and are untouched.",
  "drop schema if exists supabase_migrations cascade;",
  "drop schema public cascade;",
  "create schema public;",
  "grant usage on schema public to postgres, anon, authenticated, service_role;",
  "grant all on schema public to postgres, service_role;",
];

const files = (await readdir(MIGRATIONS_DIR))
  .filter((file) => file.endsWith(".sql"))
  .sort();

const parts = [
  "-- Generated by `pnpm db:bundle`. Paste into the Supabase SQL editor and run once.",
  ...(RESET ? ["", ...RESET_BLOCK] : []),
  "",
  "create schema if not exists supabase_migrations;",
  "create table if not exists supabase_migrations.schema_migrations (",
  "  version    text primary key,",
  "  statements text[],",
  "  name       text",
  ");",
];

for (const file of files) {
  const version = file.split("_")[0];
  const name = file.replace(/^\d+_/, "").replace(/\.sql$/, "");
  const sql = await readFile(join(MIGRATIONS_DIR, file), "utf8");

  parts.push(
    "",
    `-- ${"═".repeat(60)}`,
    `-- ${file}`,
    `-- ${"═".repeat(60)}`,
    "",
    sql.trimEnd(),
    "",
    `insert into supabase_migrations.schema_migrations (version, name)`,
    `values ('${version}', '${name}') on conflict (version) do nothing;`,
  );
}

parts.push("", "select count(*) as catalog_items from public.catalog_items;", "");

await writeFile(OUTPUT, parts.join("\n"), "utf8");

console.log(
  `Wrote ${OUTPUT} from ${files.length} migration(s)${RESET ? ", with a reset prelude" : ""}.`,
);
